-- 首版迁移（PostgreSQL 方言）：后端架构 §4 全部表，与 mysql 方言首版
-- 逐表对应（列 / 索引 / 默认值语义一致，版本号一一对应）。
-- 单文件注解格式（Up / Down 两段）：goose v3 Provider 将每个 .sql 文件
-- 视为一条迁移，不支持 .up.sql/.down.sql 成对命名。
-- 类型映射口径：自增主键用 GENERATED BY DEFAULT AS IDENTITY（BY DEFAULT
-- 保留显式插入能力，setup 固定 ID=1 可用）；布尔语义与窄整型列用 SMALLINT
-- （Go 侧 int8 映射不变）；二进制列用 BYTEA（长度上限交应用层校验）；
-- 大文本列统一 TEXT；时间列用 TIMESTAMP（不带时区）；存储引擎与字符集等
-- 表选项子句删除。
-- 命名空间差异：PG 的索引与唯一约束名是 schema 全局（MySQL 按表隔离），
-- 跨表同名者加表名前缀（uk_oidc_client_client_id、
-- idx_user_credential_user_kind、idx_user_credential_webauthn_user_kind、
-- idx_user_thirdparty_bind_user、idx_oidc_refresh_token_user），列覆盖
-- 不变；user 是 PG 保留字，裸 SQL 须写 "user"。
-- 列内注释以 -- 行内注释保留，不写 COMMENT ON。
-- CREATE TABLE 使用 IF NOT EXISTS 保持可重入（对齐 mysql 版语义）；PG DDL
-- 具事务性且 goose 默认按事务执行 SQL 迁移：失败的迁移整体回滚、无半成
-- 品残留（§3.16 失败与恢复在 PG 侧的简化），重跑 migrate up 即重试同版本。
-- 种子数据边界（§3.16）：迁移只管结构，不含 INSERT；默认 settings 由启动
-- 预热补齐（§4.7），管理员 ID=1 由 setup 代码插入（§3.15）。

-- +goose Up

CREATE TABLE IF NOT EXISTS provider (
  id             BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  provider_key   VARCHAR(64)  NOT NULL, -- 全局唯一标识，逻辑引用使用
  union_provider VARCHAR(64)  NOT NULL, -- Union ID 归属 Provider
  display_name   VARCHAR(128) NOT NULL, -- 展示名，如“QQ”“阿里云短信”
  category       VARCHAR(32)  NOT NULL, -- oauth|captcha|sms|email|storage|notify|union
  type           VARCHAR(64)  NOT NULL, -- qq|wechat_mp|turnstile|aliyun_sms|s3|local|...

  enable_signin  SMALLINT     NOT NULL DEFAULT 1, -- 允许用于登录
  enable_signup  SMALLINT     NOT NULL DEFAULT 1, -- 允许该渠道建号；关闭则未绑定用户不能建号（登录仍返回 binding_required，信封 binding.allow_signup=false，前端置灰建号入口）
  auto_bind      SMALLINT     NOT NULL DEFAULT 0, -- 按邮箱/手机号自动绑定已有账号
  auto_bind_fields VARCHAR(128) NOT NULL DEFAULT 'email,phone',
  is_enabled     SMALLINT     NOT NULL DEFAULT 1,

  ui_group       VARCHAR(32)  NOT NULL DEFAULT 'social', -- social|enterprise|dev|other
  sort_order     INTEGER      NOT NULL DEFAULT 0,
  icon_url       VARCHAR(512) NOT NULL DEFAULT '',

  ext            BYTEA, -- provider.Ext 序列化后（Protobuf，业务上限 1 MiB，写入前校验，见 §4.0）

  remark         VARCHAR(512) NOT NULL DEFAULT '',
  created_at     TIMESTAMP    NOT NULL,
  updated_at     TIMESTAMP    NOT NULL,
  CONSTRAINT uk_provider_key UNIQUE (provider_key)
);
CREATE INDEX IF NOT EXISTS idx_category_enabled ON provider (category, is_enabled);
CREATE INDEX IF NOT EXISTS idx_type ON provider (type);

CREATE TABLE IF NOT EXISTS "user" (
  id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  username       VARCHAR(64)  NOT NULL, -- 用户名必选，设置后不可改（需求 §4.1.1）
  phone          VARCHAR(32)  DEFAULT NULL,
  email          VARCHAR(128) DEFAULT NULL,
  phone_verified SMALLINT     NOT NULL DEFAULT 0,
  email_verified SMALLINT     NOT NULL DEFAULT 0,
  nickname       VARCHAR(128) NOT NULL DEFAULT '',
  avatar_url     VARCHAR(512) NOT NULL DEFAULT '',
  user_status    SMALLINT     NOT NULL DEFAULT 1, -- 1正常 0禁用；列名避开 API 信封保留字 status（接口文档 §1.0）
  mfa_required   SMALLINT     NOT NULL DEFAULT 0, -- 用户自助两步验证开关；1开启 0关闭
  epoch          SMALLINT     NOT NULL DEFAULT 0, -- 安全版本号，改密/重置/管理员禁用时递增；递增结果 > 30000 时回绕为 1（跳过 0，由后端逻辑控制，不由DB控制）
  last_login_at  TIMESTAMP,
  created_at     TIMESTAMP    NOT NULL,
  updated_at     TIMESTAMP    NOT NULL,
  CONSTRAINT uk_username UNIQUE (username),
  CONSTRAINT uk_phone UNIQUE (phone),
  CONSTRAINT uk_email UNIQUE (email)
);

CREATE TABLE IF NOT EXISTS user_profile (
  user_id    BIGINT PRIMARY KEY,
  gender     SMALLINT     DEFAULT 0,
  birthday   DATE,
  locale     VARCHAR(16)  DEFAULT '',
  timezone   VARCHAR(64)  DEFAULT '',
  extra      BYTEA, -- msgpack 序列化的扩展资料
  updated_at TIMESTAMP NOT NULL
);

-- 统一凭证表：一行一种凭证，新增凭证类型不加列
CREATE TABLE IF NOT EXISTS user_credential (
  id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id       BIGINT       NOT NULL,
  kind          VARCHAR(32)  NOT NULL, -- password|totp|webauthn|recovery_code
  secret        BYTEA        NOT NULL, -- password=argon2id 串；totp=Base32 明文密钥
  label         VARCHAR(128) NOT NULL DEFAULT '', -- 用户自定义名称，如“MacBook Touch ID”
  meta          BYTEA, -- credential.Meta 的 Protobuf 序列化
  is_enabled    SMALLINT     NOT NULL DEFAULT 1,
  last_used_at  TIMESTAMP,
  created_at    TIMESTAMP    NOT NULL,
  updated_at    TIMESTAMP    NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_user_credential_user_kind ON user_credential (user_id, kind);

-- WebAuthn 额外有一个凭据表
CREATE TABLE IF NOT EXISTS user_credential_webauthn (
  id            BIGINT PRIMARY KEY, -- 主键，与 user_credential.id 保持一致（非自增）
  user_id       BIGINT       NOT NULL,
  kind          VARCHAR(32)  NOT NULL DEFAULT 'webauthn',
  public_key    BYTEA, -- webauthn 公钥（COSE）
  credential_id VARCHAR(512) NOT NULL DEFAULT '', -- webauthn 凭据 ID（base64url）
  sign_count    BIGINT       NOT NULL DEFAULT 0, -- webauthn 签名计数，防克隆
  CONSTRAINT uk_kind_credid UNIQUE (kind, credential_id)
);
CREATE INDEX IF NOT EXISTS idx_user_credential_webauthn_user_kind ON user_credential_webauthn (user_id, kind);

-- Union 归并不设独立列 / 独立索引：由额外一行 Union Provider（category=union）
-- 绑定记录承担，该行 open_id 即 unionid 值（§4.3 / §12.7）。
CREATE TABLE IF NOT EXISTS user_thirdparty_bind (
  id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id    BIGINT       NOT NULL,
  provider_key VARCHAR(64) NOT NULL, -- 引用 provider.provider_key，不存渠道类型
  open_id    VARCHAR(128) NOT NULL,
  nickname   VARCHAR(128) NOT NULL DEFAULT '',
  avatar_url VARCHAR(512) NOT NULL DEFAULT '',
  extra      BYTEA, -- msgpack 序列化的第三方原始资料（仅排查用）
  created_at TIMESTAMP    NOT NULL,
  CONSTRAINT uk_provider_openid UNIQUE (provider_key, open_id)
);
CREATE INDEX IF NOT EXISTS idx_user_thirdparty_bind_user ON user_thirdparty_bind (user_id);

CREATE TABLE IF NOT EXISTS sso_client (
  id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  client_id     VARCHAR(64)  NOT NULL,
  client_secret CHAR(64) NOT NULL,
  name          VARCHAR(128) NOT NULL DEFAULT '',
  redirect_uris BYTEA NOT NULL, -- client.RedirectUris 的 Protobuf 序列化
  login_methods BYTEA NOT NULL, -- client.ClientLoginMethods 的 Protobuf 序列化；空 = 跟随全局（接口文档 §2.1）
  oauth_providers BYTEA NOT NULL, -- client.ClientOauthProviders 的 Protobuf 序列化；空 = 跟随全局
  default_redirect_uri VARCHAR(1024) NOT NULL DEFAULT '', -- 登录完成默认回跳地址；空 = 未配置（非空须命中 redirect_uris 白名单，接口文档 §5.5）
  template_key  VARCHAR(64)  NOT NULL DEFAULT '', -- 绑定的自定义模板 key
  template_vars TEXT, -- 模板变量 JSON
  is_enabled    SMALLINT NOT NULL DEFAULT 1,
  created_at    TIMESTAMP NOT NULL,
  updated_at    TIMESTAMP NOT NULL,
  CONSTRAINT uk_client_id UNIQUE (client_id)
);

CREATE TABLE IF NOT EXISTS oidc_client (
  id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  client_id     VARCHAR(64)  NOT NULL,
  client_secret CHAR(64) NOT NULL,
  name          VARCHAR(128) NOT NULL DEFAULT '',
  redirect_uris BYTEA NOT NULL, -- client.RedirectUris 的 Protobuf 序列化
  scopes        VARCHAR(512) NOT NULL DEFAULT 'openid,profile,email',
  access_token_ttl  INTEGER NOT NULL DEFAULT 3600,
  refresh_token_ttl INTEGER NOT NULL DEFAULT 2592000,
  template_key  VARCHAR(64)  NOT NULL DEFAULT '', -- 绑定的自定义模板 key
  template_vars TEXT, -- 模板变量 JSON
  is_enabled    SMALLINT NOT NULL DEFAULT 1,
  created_at    TIMESTAMP NOT NULL,
  updated_at    TIMESTAMP NOT NULL,
  -- 约束名与 sso_client 的 uk_client_id 同名，PG 约束名 schema 全局，加表名前缀
  CONSTRAINT uk_oidc_client_client_id UNIQUE (client_id)
);

-- 自定义模板（§4.9）：DB 自定义模板，与常驻内存的内置模板双轨共存
-- （§3.13）；无版本号、无内置标记列，缓存失效靠写路径 DEL（§5.1）。
CREATE TABLE IF NOT EXISTS template (
  id           BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  template_key VARCHAR(64)  NOT NULL, -- 模板 key；不得与内置模板 key 同名
  name         VARCHAR(128) NOT NULL DEFAULT '',
  content      TEXT         NOT NULL, -- 模板 HTML 原文
  created_at   TIMESTAMP    NOT NULL,
  updated_at   TIMESTAMP    NOT NULL,
  CONSTRAINT uk_template_key UNIQUE (template_key)
);

-- 刷新令牌存库：需要可吊销、可列表、有效期长
CREATE TABLE IF NOT EXISTS oidc_refresh_token (
  id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  token_hash CHAR(64)     NOT NULL, -- sha256(refresh_token)
  client_id  VARCHAR(64)  NOT NULL,
  user_id    BIGINT       NOT NULL,
  session_id VARCHAR(64)  NOT NULL DEFAULT '',
  scopes     VARCHAR(512) NOT NULL DEFAULT '',
  revoked_at TIMESTAMP,
  expires_at TIMESTAMP NOT NULL,
  created_at TIMESTAMP NOT NULL,
  CONSTRAINT uk_token_hash UNIQUE (token_hash)
);
CREATE INDEX IF NOT EXISTS idx_oidc_refresh_token_user ON oidc_refresh_token (user_id);
CREATE INDEX IF NOT EXISTS idx_session ON oidc_refresh_token (session_id);

CREATE TABLE IF NOT EXISTS event_log (
  id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  event      VARCHAR(48)  NOT NULL, -- login_success|change_password|reset_password|bind_phone|bind_email|enable_mfa|disable_mfa|webauthn_register|webauthn_delete|thirdparty_bind|thirdparty_unbind|admin_disable_user|admin_reset_password|provider_create|provider_update|settings_update|...
  actor_type VARCHAR(16)  NOT NULL, -- user|admin|system
  actor_id   BIGINT       NOT NULL DEFAULT 0, -- user=该用户 uid；admin=操作管理员 uid；system=0（见下方记录范围）
  user_id    BIGINT       NOT NULL DEFAULT 0, -- 被操作对象；自身操作时与 actor_id 相同
  client_id  VARCHAR(64)  NOT NULL DEFAULT '', -- OIDC 客户端，登录类事件填充
  amr        VARCHAR(128) NOT NULL DEFAULT '', -- 登录类事件：通过的认证方法，如 pwd,otp,mfa
  ip         VARCHAR(64)  NOT NULL DEFAULT '',
  ua         VARCHAR(512) NOT NULL DEFAULT '',
  target     VARCHAR(128) NOT NULL DEFAULT '', -- 操作目标，如 provider_key
  detail     BYTEA, -- msgpack 序列化的附加信息
  created_at TIMESTAMP    NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_actor_time ON event_log (actor_type, actor_id, created_at);
CREATE INDEX IF NOT EXISTS idx_user_time  ON event_log (user_id, created_at);
CREATE INDEX IF NOT EXISTS idx_event_time ON event_log (event, created_at);
CREATE INDEX IF NOT EXISTS idx_time ON event_log (created_at);

CREATE TABLE IF NOT EXISTS settings (
  k          VARCHAR(64)  PRIMARY KEY, -- 键名，与接口文档 §5.6 完全同名
  v          TEXT         NOT NULL, -- JSON 编码值（标量也按 JSON 存，便于统一反序列化）
  updated_at TIMESTAMP    NOT NULL,
  updated_by BIGINT       NOT NULL DEFAULT 0 -- 操作管理员 uid
);

-- 用户权限点映射（§4.8）：行存在即持有，首版仅 superadmin（安装时授予）。
CREATE TABLE IF NOT EXISTS user_permission (
  user_id BIGINT      NOT NULL, -- 用户 ID，引用 user.id
  point   VARCHAR(32) NOT NULL, -- 权限点标识；首版仅 superadmin（安装时自动授予）
  PRIMARY KEY (user_id, point)
);

-- 授权记录（§4.5）：用户对客户端的长期授权口径，与
-- oidc_refresh_token.scopes 的单次令牌快照互不替代。
CREATE TABLE IF NOT EXISTS oidc_consent (
  id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id    BIGINT      NOT NULL, -- 引用 user.id
  client_id  VARCHAR(64) NOT NULL, -- oidc_client.client_id
  scopes     VARCHAR(512) NOT NULL DEFAULT '', -- 已授权 scope 并集，空格分隔
  created_at TIMESTAMP    NOT NULL,
  updated_at TIMESTAMP    NOT NULL,
  CONSTRAINT uk_user_client UNIQUE (user_id, client_id)
);

-- 存量客户端补齐 openid（openid 全链路强制的前置，接口文档 §5.5）：
-- FIND_IN_SET 判重的 PG 等价写法，WHERE 限定未含者，重复执行不重复补；
-- 逗号分隔口径不变。
UPDATE oidc_client
SET scopes = scopes || ',openid'
WHERE NOT ('openid' = ANY(string_to_array(scopes, ',')));

-- +goose Down

-- 回退脚本（§3.16：down 按工具标准提供，日常升级不使用；数据备份责任
-- 归部署方，执行迁移前自行备份）。倒序删除全部表；PG 删表随行删除其上
-- 索引与约束，无需单独 DROP。
-- openid 补齐不做回退——无从区分哪些客户端原本缺 openid，删补齐值会伤
-- 存量数据；down 只负责删表。
DROP TABLE IF EXISTS oidc_consent;
DROP TABLE IF EXISTS user_permission;
DROP TABLE IF EXISTS settings;
DROP TABLE IF EXISTS event_log;
DROP TABLE IF EXISTS oidc_refresh_token;
DROP TABLE IF EXISTS template;
DROP TABLE IF EXISTS oidc_client;
DROP TABLE IF EXISTS sso_client;
DROP TABLE IF EXISTS user_thirdparty_bind;
DROP TABLE IF EXISTS user_credential_webauthn;
DROP TABLE IF EXISTS user_credential;
DROP TABLE IF EXISTS user_profile;
DROP TABLE IF EXISTS "user";
DROP TABLE IF EXISTS provider;
